BEGIN;
SET search_path=public,extensions;
SELECT plan(38);
CREATE TEMP TABLE password_profile AS SELECT '{"name":"د. أحمد علي","address":"عنوان تجربة محلية","code_region":"cairo","is_center":true,"branches":[{"name":"التجمع","address":"عنوان فرع التجربة","phone":"01077411112"}],"doctors":[{"name":"محمد حسن","phone":""}],"doctor_code":"9999","custom_prices":{"secret":1}}'::jsonb AS value;
CREATE TEMP TABLE password_new AS SELECT public.register_doctor_password_account('01077411111','doctor-password-qa@local.test','local-password-test-123',(SELECT value FROM password_profile),'new') AS result;
SELECT is((SELECT result->>'status' FROM password_new),'approved','New doctor enters immediately');
SELECT ok((SELECT result->>'doctor_code' ~ '^1[0-9]{3}$' FROM password_new),'Approved regional code assigned');
SELECT ok(EXISTS(SELECT 1 FROM auth.users WHERE email='doctor-password-qa@local.test' AND substring(encrypted_password,5,2)='10' AND encrypted_password<>'local-password-test-123' AND crypt('local-password-test-123',encrypted_password)=encrypted_password),'Native bcrypt hash uses cost 10, never plaintext');
SELECT ok(EXISTS(SELECT 1 FROM auth.users WHERE email='doctor-password-qa@local.test' AND phone='201077411111' AND phone_confirmed_at IS NULL AND raw_app_meta_data->>'doctor_verification'='unverified_password'),'Phone alias explicitly has no possession proof');
SELECT ok(NOT (public.resolve_doctor_password_login('01077411111','wrong-password')->>'success')::boolean,'Wrong password cannot enumerate login email');
SELECT is(public.resolve_doctor_password_login('01077411111','local-password-test-123')->>'email','doctor-password-qa@local.test','Valid password resolves only its own alias');
SELECT ok(EXISTS(SELECT 1 FROM public.doctors d JOIN public.users u ON u.entity_id=d.id WHERE u.email='doctor-password-qa@local.test' AND d.name='أحمد علي' AND d.custom_prices='{}'::jsonb),'New doctor strips titles and injected prices');
SELECT ok(NOT (public.register_doctor_password_account('01077422222','doctor-password-qa@local.test','other-password-123',(SELECT value FROM password_profile),'new')->>'success')::boolean,'Duplicate email does not reset an existing account');
SELECT ok(NOT (public.register_doctor_password_account('01077422222','weak-password-qa@local.test','short',(SELECT value FROM password_profile),'new')->>'success')::boolean,'Weak password rejected');
SELECT ok(NOT has_table_privilege('anon','public.doctor_password_registrations','SELECT'),'Registration table is private');
SELECT ok(NOT has_function_privilege('anon','public.open_doctor_manual_access(uuid,text)','EXECUTE'),'Old device-only session exchange retired');
CREATE TEMP TABLE password_existing AS SELECT d.* FROM public._insert_doctor_profile('{"name":"محمد أحمد","phone":"01077433333","address":"عنوان سجل موجود","code_region":"other"}') d;
SELECT is(jsonb_array_length(public.find_doctor_registration_matches('01077433333')->'matches'),1,'Exact phone shows one name');
SELECT is(public.find_doctor_registration_matches('01077433333')->'matches'->0->>'address','عنوان سجل موجود','Lookup prefills the owner-authorized clinic address');
CREATE TEMP TABLE password_claim AS SELECT public.register_doctor_password_account('01077433333','doctor-claim-qa@local.test','local-password-claim-123',(SELECT value FROM password_profile),'existing',(SELECT id FROM password_existing)) AS result;
SELECT is((SELECT result->>'status' FROM password_claim),'pending','Self-claimed existing record always needs review');
SELECT ok(EXISTS(SELECT 1 FROM auth.users a JOIN public.users u ON u.auth_id=a.id WHERE a.email='doctor-claim-qa@local.test' AND a.banned_until>clock_timestamp() AND NOT u.is_active AND u.entity_id IS NULL),'Pending Auth account cannot obtain a session or existing entity');
SELECT ok(NOT (public.resolve_doctor_password_login('01077433333','local-password-claim-123')->>'success')::boolean,'Pending phone alias cannot open a session');
SELECT throws_ok($q$ SELECT public.review_doctor_password_registration((SELECT id FROM public.doctor_password_registrations WHERE phone='201077433333'),true,(SELECT id FROM password_existing)) $q$,'P0001','غير مصرح بمراجعة التسجيل','Public cannot approve their claim');
INSERT INTO auth.users(id,instance_id,aud,role,email,created_at,updated_at) VALUES('82000000-0000-0000-0000-000000000088','00000000-0000-0000-0000-000000000000','authenticated','authenticated','password-review-qa@local.test',now(),now());
INSERT INTO public.users(id,auth_id,username,role,name,is_active) VALUES('83000000-0000-0000-0000-000000000088','82000000-0000-0000-0000-000000000088','password_review_qa','admin','مراجعة تجريبية',true);
SELECT set_config('request.jwt.claim.sub','82000000-0000-0000-0000-000000000088',true);
SELECT ok((public.review_doctor_password_registration((SELECT id FROM public.doctor_password_registrations WHERE phone='201077433333'),true,(SELECT id FROM password_existing))->>'success')::boolean,'Staff approves the existing record');
SELECT ok(EXISTS(SELECT 1 FROM auth.users a JOIN public.users u ON u.auth_id=a.id WHERE a.email='doctor-claim-qa@local.test' AND a.banned_until IS NULL AND u.is_active AND u.entity_id=(SELECT id FROM password_existing)),'Approval activates the same chosen-password identity');
SELECT ok(EXISTS(SELECT 1 FROM auth.users WHERE email='doctor-claim-qa@local.test' AND crypt('local-password-claim-123',encrypted_password)=encrypted_password),'Approval does not change the doctor password');
CREATE TEMP TABLE password_invited AS SELECT d.* FROM public._insert_doctor_profile('{"name":"محمود علي","phone":"01077444444","address":"عنوان سجل مدعو","code_region":"other"}') d;
CREATE TEMP TABLE password_invite AS SELECT public.create_doctor_portal_invitation((SELECT id FROM password_invited)) AS result;
SELECT ok((public.inspect_doctor_portal_invitation((SELECT result->>'token' FROM password_invite))->>'success')::boolean,'Issued invitation opens the intended doctor');
CREATE TEMP TABLE password_invite_signup AS SELECT public.register_doctor_password_account('01077444444','doctor-invite-qa@local.test','local-password-invite-123',(SELECT value FROM password_profile),'invited',NULL,(SELECT result->>'token' FROM password_invite)) AS result;
SELECT is((SELECT result->>'status' FROM password_invite_signup),'approved','Invitation links immediately without review');
SELECT ok(EXISTS(SELECT 1 FROM public.users WHERE email='doctor-invite-qa@local.test' AND entity_id=(SELECT id FROM password_invited)),'Invitation binds to its doctor, not caller supplied profile');
SELECT ok(NOT (public.inspect_doctor_portal_invitation((SELECT result->>'token' FROM password_invite))->>'success')::boolean,'Consumed invitation cannot be reused');
SELECT is((SELECT address FROM public.doctors WHERE id=(SELECT id FROM password_invited)),'عنوان سجل مدعو','Existing doctor profile unchanged');
CREATE TEMP TABLE password_expired_doc AS SELECT d.* FROM public._insert_doctor_profile('{"name":"حسن علي","phone":"01077455555","address":"عنوان سجل دعوة","code_region":"other"}') d;
CREATE TEMP TABLE password_expired AS SELECT public.create_doctor_portal_invitation((SELECT id FROM password_expired_doc)) AS result;
UPDATE public.doctor_portal_invitations SET expires_at=now()-interval '1 day' WHERE doctor_id=(SELECT id FROM password_expired_doc);
SELECT ok(NOT (public.inspect_doctor_portal_invitation((SELECT result->>'token' FROM password_expired))->>'success')::boolean,'Expired invitation rejected');
SELECT ok(NOT (public.register_doctor_password_account('01077455555','forged-claim-qa@local.test','local-password-forged-123',(SELECT value FROM password_profile),'existing',(SELECT id FROM password_existing))->>'success')::boolean,'Cannot claim an unrelated doctor ID');
SELECT ok(NOT (public.register_doctor_password_account('01077433333','duplicate-qa@local.test','local-password-duplicate-123',(SELECT value FROM password_profile),'new')->>'success')::boolean,'Existing record cannot be duplicated through new signup');
SELECT ok(NOT has_function_privilege('anon','public.create_doctor_portal_invitation(uuid)','EXECUTE'),'Only authorized staff can issue invitations');
CREATE TEMP TABLE password_staff AS SELECT public.admin_create_password_auth_user('staff-password-qa@local.test','staff-password-123') AS auth_id;
SELECT ok(EXISTS(SELECT 1 FROM auth.users WHERE id=(SELECT auth_id FROM password_staff) AND banned_until>clock_timestamp()),'Staff creation keeps orphan identity banned');
SELECT throws_ok($q$ SELECT public.admin_activate_password_auth_user((SELECT auth_id FROM password_staff)) $q$,'P0001','أضف بيانات المستخدم واربط الطبيب أولًا','Unbound staff identity cannot activate');
INSERT INTO public.users(id,auth_id,username,email,role,name,is_active) VALUES(gen_random_uuid(),(SELECT auth_id FROM password_staff),'password_staff_qa','staff-password-qa@local.test','coordinator','موظف تجربة',true);
SELECT lives_ok($q$ SELECT public.admin_activate_password_auth_user((SELECT auth_id FROM password_staff)) $q$,'Admin completes staff creation despite disabled public signup');
SELECT ok(EXISTS(SELECT 1 FROM auth.users WHERE id=(SELECT auth_id FROM password_staff) AND banned_until IS NULL),'Completed staff identity is available');
SELECT throws_ok($q$ SELECT public.admin_reset_password((SELECT id FROM public.users WHERE email='doctor-password-qa@local.test'),'short') $q$,'P0001','كلمة المرور لا تقل عن 8 أحرف، والحد الأقصى 72 بايت','Doctor reset enforces password policy');
SELECT lives_ok($q$ SELECT public.admin_reset_password((SELECT id FROM public.users WHERE email='doctor-password-qa@local.test'),'reset-password-test-123') $q$,'Admin resets a forgotten doctor password');
SELECT ok(NOT (public.resolve_doctor_password_login('01077411111','local-password-test-123')->>'success')::boolean,'Previous password fails after reset');
SELECT ok((public.resolve_doctor_password_login('01077411111','reset-password-test-123')->>'success')::boolean,'Phone login uses the reset Auth password');
SELECT set_config('request.jwt.claim.sub','',true);
UPDATE public.users SET is_active=false WHERE auth_id='82000000-0000-0000-0000-000000000088';
SELECT set_config('request.jwt.claim.sub','82000000-0000-0000-0000-000000000088',true);
SELECT throws_ok($q$ SELECT public.admin_reset_password((SELECT id FROM public.users WHERE email='doctor-password-qa@local.test'),'other-password-test-123') $q$,'P0001','غير مصرح بإعادة تعيين كلمة المرور','Deactivated admin cannot reset passwords');
SELECT * FROM finish();
ROLLBACK;
